class SegmentTree {
  constructor(nums) {
    this.n = nums.length;
    this.tree = new Array(2 * this.n).fill(0);
    for (let i = 0; i < this.n; i++) this.tree[this.n + i] = nums[i];
    for (let i = this.n - 1; i > 0; i--) this.tree[i] = this.tree[2 * i] + this.tree[2 * i + 1];
  }
  update(index, value) {
    let i = index + this.n;
    this.tree[i] = value;
    while (i > 1) {
      i >>= 1;
      this.tree[i] = this.tree[2 * i] + this.tree[2 * i + 1];
    }
  }
  query(left, right) {
    let sum = 0;
    let l = left + this.n, r = right + this.n + 1;
    while (l < r) {
      if (l & 1) sum += this.tree[l++];
      if (r & 1) sum += this.tree[--r];
      l >>= 1;
      r >>= 1;
    }
    return sum;
  }
}

const st = new SegmentTree([1, 3, 5, 7, 9, 11]);
console.log(st.query(1, 3)); // 3+5+7 = 15
st.update(1, 10);
console.log(st.query(1, 3)); // 10+5+7 = 22

